// ── Classic ordering quiz — trace this carefully ──────────────
console.log('A');                          // synchronous

setTimeout(() => console.log('B'), 0);     // task queue

Promise.resolve()
  .then(() => console.log('C'))            // microtask
  .then(() => console.log('D'));           // microtask (chained)

queueMicrotask(() => console.log('E'));    // microtask

console.log('F');                          // synchronous

// Output: A, F, C, E, D, B
//
// Step-by-step:
//   A, F   — synchronous code in the current script task
//   C      — first .then microtask fires
//   E      — queueMicrotask fires (queued before C resolved chained .then)
//   D      — second chained .then fires (queued when C's .then ran)
//   B      — setTimeout callback from task queue (after all microtasks)

// ── Nested microtask scheduling ───────────────────────────────
Promise.resolve().then(() => {
  console.log('microtask 1');
  // Scheduling another microtask from within a microtask:
  queueMicrotask(() => console.log('microtask 1b — same drain pass'));
});
Promise.resolve().then(() => console.log('microtask 2'));

// Output: microtask 1, microtask 2, microtask 1b
// All three run before any task or render. '1b' was added mid-drain
// but the engine keeps going until the microtask queue is truly empty.

// ── async/await desugared to raw Promises ─────────────────────
async function loadUser(id) {
  const res = await fetch(`/api/users/${id}`); // suspends here
  const user = await res.json();               // suspends again
  return user;                                 // resolves returned Promise
}

// Exactly equivalent raw-Promise form:
function loadUserRaw(id) {
  return fetch(`/api/users/${id}`)
    .then(res => res.json());
}

// Each 'await' is a .then() whose continuation is a microtask.
// The async function returns a Promise immediately;
// callers receive the result via .then() or another await.

// ── Demonstrating that await does NOT block ───────────────────
async function demo() {
  console.log('before await');
  await Promise.resolve(); // yields; continuation is a microtask
  console.log('after await'); // runs as a microtask
}

console.log('start');
demo();
console.log('end'); // runs BEFORE 'after await'

// Output: start, before await, end, after await

// ── Chunked array processing: yield between chunks ────────────
// Problem: processing 500,000 items synchronously blocks the UI
// Solution: split into chunks, yield to the event loop between each

async function processLargeArray(items, chunkSize = 500) {
  const results = [];

  for (let i = 0; i < items.length; i += chunkSize) {
    const chunk = items.slice(i, i + chunkSize);

    // Process this chunk synchronously (fast)
    for (const item of chunk) {
      results.push(item * item); // example: squaring each number
    }

    // Yield to event loop: allow rendering + user events to run
    // setTimeout(resolve, 0) deposits a task, so the render frame
    // and any pending microtasks run before we continue.
    await new Promise(resolve => setTimeout(resolve, 0));
  }

  return results;
}

// ── Web Worker: off-main-thread computation ───────────────────
// worker.js (runs in a separate thread)
self.addEventListener('message', (event) => {
  const { items } = event.data;
  const result = items.map(x => x * x); // heavy computation here
  self.postMessage({ result });
});

// main.js
const worker = new Worker('./worker.js');
worker.postMessage({ items: [1, 2, 3, 4, 5] });
worker.addEventListener('message', (event) => {
  console.log('Result from worker:', event.data.result);
  // [1, 4, 9, 16, 25]
});

// ── requestAnimationFrame animation loop ──────────────────────
let startTime = null;
let animating = true;

function animateBox(element) {
  function frame(timestamp) {
    if (!animating) return;

    if (!startTime) startTime = timestamp;
    const elapsed = timestamp - startTime;

    // Move 100px over 1 second (100ms = 10px)
    const progress = Math.min(elapsed / 1000, 1);
    const xPos = progress * 200; // move 200px total
    element.style.transform = `translateX(${xPos}px)`;

    if (progress < 1) {
      requestAnimationFrame(frame); // schedule next frame
    } else {
      console.log('Animation complete');
    }
  }
  requestAnimationFrame(frame);
}

// ── Parallel vs sequential awaits ────────────────────────────
// SEQUENTIAL (slow): each fetch waits for the previous
async function sequentialFetch(ids) {
  const results = [];
  for (const id of ids) {
    const res = await fetch(`/api/items/${id}`); // awaits each one
    results.push(await res.json());
  }
  return results;
}

// PARALLEL (fast): all fetches start simultaneously
async function parallelFetch(ids) {
  const promises = ids.map(id =>
    fetch(`/api/items/${id}`).then(r => r.json())
  );
  return Promise.all(promises); // wait for all at once
}

// ── Queue priority reference ──────────────────────────────────
//
// Execution order within one event loop turn:
//
//  1. Current synchronous code (call stack)
//  2. process.nextTick callbacks  [Node.js only — highest priority]
//  3. Microtasks: Promise.then, queueMicrotask, MutationObserver
//     └─ ALL drained before anything below
//  4. requestAnimationFrame callbacks  [browser only]
//  5. Browser render: style, layout, paint
//  6. ONE macrotask from the task queue:
//     setTimeout, setInterval, I/O events, MessageChannel, click handlers
//  Repeat from step 1.

// ── Traps cheat-sheet ─────────────────────────────────────────

// TRAP 1: Infinite microtask chain starves the renderer
async function bad() {
  while (true) {
    await Promise.resolve(); // queue microtask, loop forever
    // Renderer never runs!
  }
}
// FIX: yield to task queue periodically
async function good() {
  while (true) {
    await new Promise(r => setTimeout(r, 0)); // yields to task queue
    // Renderer gets a frame opportunity each iteration
  }
}

// TRAP 2: Reading layout in a loop causes thrashing
function layoutThrash(elements) {
  elements.forEach(el => {
    const height = el.offsetHeight; // forces layout recalculation!
    el.style.height = (height + 10) + 'px'; // triggers another layout
  });
}
// FIX: batch reads, then batch writes
function noThrash(elements) {
  const heights = elements.map(el => el.offsetHeight); // read all first
  elements.forEach((el, i) => {
    el.style.height = (heights[i] + 10) + 'px'; // then write all
  });
}

// TRAP 3: Forgetting that Promise.then is always async
let value = null;
Promise.resolve(42).then(v => { value = v; });
console.log(value); // null! .then hasn't run yet
// The microtask runs AFTER this synchronous console.log

// TRAP 4: Sequential await inside a loop
async function slow(ids) {
  for (const id of ids) {
    await fetch(`/api/${id}`); // 3 fetches, 3 round trips, sequential
  }
}
async function fast(ids) {
  await Promise.all(ids.map(id => fetch(`/api/${id}`))); // parallel
}
